\renewcommand{\cftsecnumwidth}{\cftchapnumwidth}
\renewcommand{\cftsubsecnumwidth}{\cftsecnumwidth}
\renewcommand{\cftsubsubsecnumwidth}{\cftsubsecnumwidth}

% Fonction pour ajouter des espaces entre les titres de sections et leurs numéros
\newcommand{\addcftlinenumbers}[1]{%
