```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int countWordOccurrences(string fileName, string wordToSearch) {
    int count = 0;
    ifstream file(fileName); // ouvre le fichier en lecture

    if (!file.is_open()) { // vérifie si le fichier a pu être ouvert
        cout << "Erreur : Impossible d'ouvrir le fichier " << fileName << endl;
        return -1; // renvoie une valeur négative pour indiquer une erreur
    }

    string line; // variable pour stocker une ligne lue dans le fichier

    while (getline(file, line)) { // lit chaque ligne du fichier
        // transforme la ligne en minuscules pour ne pas être sensible à la casse
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // compte le nombre d'occurrences du mot à rechercher dans la ligne
        size_t pos = line.find(wordToSearch);
        while (pos != string::npos) {
            count++;
            pos = line.find(wordToSearch, pos + 1); // recherche le prochain mot correspondant dans la ligne
        }
    }

    file.close(); // ferme le fichier après avoir fini de lire ses lignes

    return count; // retourne le nombre d'occurrences du mot spécifique dans le fichier
}

