      if (arr1[i] === arr2[j]) {
        if (!commonElements.includes(arr1[i])) { // Eviter les doublons en vérifiant qu'il n'existe pas déjà dans le tableau des éléments communs
          commonElements.push(arr1[i]);
        }
      }
    }
  }

  return commonElements;
}
